const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const h=escapeHTML;
let state=null,session='',view='all',filter='all',search='',page=1,sort='createdAt',sortAsc=false,selected=new Set(),detailId=null,settingsDraft=null,settingsTab='general',queueId='main',polling=false;
const history=[];let previousComplete=new Set(),initialized=false,refreshTimer;
const t=(ar,en)=>state?.settings.language==='en'?en:ar;
const messageText=value=>state?.settings.language==='ar'?String(value??''):englishMessage(value);
const catNames=()=>({all:t('كل التحميلات','All downloads'),compressed:t('ملفات مضغوطة','Archives'),documents:t('مستندات','Documents'),music:t('صوتيات','Audio'),programs:t('برامج','Applications'),video:t('فيديو','Video'),other:t('ملفات أخرى','Other files')});
const catIcons={compressed:'archive',documents:'file',music:'music',programs:'code',video:'video',other:'file'};
const colors={compressed:'#dab46d',documents:'#79a7d7',music:'#c892ac',programs:'#8db5a4',video:'#a69bcc'};
const isActive=d=>['downloading','probing','processing'].includes(d.status);
const statusText=status=>({pending:t('بانتظار التأكيد','Awaiting confirmation'),queued:t('في الانتظار','Queued'),paused:t('متوقف مؤقتاً','Paused'),limited:t('حد البيانات','Data limit'),downloading:t('جارٍ التحميل','Downloading'),probing:t('جارٍ الاتصال','Connecting'),processing:t('معالجة الوسائط','Processing'),complete:t('مكتمل','Completed'),error:t('تعذر التحميل','Failed')})[status]||status;
function size(n,dec=1){if(!n)return'0 B';const units=['B','KB','MB','GB','TB'],i=Math.min(4,Math.floor(Math.log(Math.max(1,n))/Math.log(1024)));return `${(n/1024**i).toFixed(i?dec:0)} ${units[i]}`;}
function percent(d){return d.status==='complete'?100:d.size?Math.min(100,d.downloaded/d.size*100):0;}
function duration(sec){if(!Number.isFinite(sec)||sec<=0)return'—';if(sec<60)return `${Math.ceil(sec)} ${t('ث','s')}`;if(sec<3600)return `${Math.floor(sec/60)} ${t('د','m')} ${Math.ceil(sec%60)} ${t('ث','s')}`;return `${Math.floor(sec/3600)}h ${Math.floor(sec%3600/60)}m`;}
function date(s){return new Date(s).toLocaleDateString(state?.settings.language==='en'?'en-GB':'ar-EG',{day:'numeric',month:'short'});}
function button(action,label,ico,cls='',extra=''){return `<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${ico?icon(ico):''}${h(label)}</button>`;}
function ib(action,label,ico,extra=''){return `<button type="button" class="icon-button" data-action="${action}" title="${h(label)}" aria-label="${h(label)}" ${extra}>${icon(ico)}</button>`;}
function badge(d){return `<span class="status-badge ${d.status}" title="${h(d.error)}">${icon(d.status==='complete'?'check':d.status==='paused'?'pause':d.status==='error'?'info':d.status==='queued'?'clock':'activity')}${h(statusText(d.status))}</span>`;}
async function api(type,data={}){
  if(window.desktopAPI){try{return await window.desktopAPI.action(type,data);}catch(e){throw Error(String(e.message).replace(/^Error invoking remote method '[^']+': (?:Error: )?/,''));}}
  const r=await fetch('/api/action',{method:'POST',headers:{'content-type':'application/json','x-flow-token':session},body:JSON.stringify({type,data})});
  const value=await r.json();if(!r.ok)throw Error(value.error);return value.result;
}
async function action(type,data={},message=''){try{const result=await api(type,data);if(message)toast(message);await refresh();return result;}catch(e){toast(e.message,true);return null;}}
async function refresh(){
  if(polling||windowClosing)return;polling=true;
  try{
    const next=window.desktopAPI?await window.desktopAPI.state():await (await fetch('/api/state',{headers:{'x-flow-token':session}})).json();
    if(next.error)throw Error(next.error);const languageChanged=state&&state.settings.language!==next.settings.language;state=next;if(state.settings.language==='en')for(const item of state.downloads)item.error=englishMessage(item.error);
    applyAppearance(state.settings.theme);document.body.classList.toggle('rtl',state.settings.language!=='en');
    document.documentElement.dir=state.settings.language==='en'?'ltr':'rtl';document.documentElement.lang=state.settings.language;
    if(!window.desktopAPI){const scale=Math.max(.8,Math.min(1.5,(state.settings.textScale||100)/100));document.body.style.zoom=scale;document.body.style.width=`${100/scale}vw`;document.body.style.height=`${100/scale}vh`;}
    if(!initialized){if(!renderNativeWindow()){renderShell();renderMain();}previousComplete=new Set(state.downloads.filter(d=>d.status==='complete').map(d=>d.id));initialized=true;}
    else{
      if(languageChanged){if(windowContext){repaintNativeLanguage();}else{renderShell();renderMain();}}renderSidebar();renderFooter();
      if(['all','active','complete','unfinished','compressed','documents','music','programs','video','other'].includes(view)||view.startsWith('queue:')||view.startsWith('saved:'))updateDownloads();
      if(view==='grabber'&&!$('#dialog').open)renderProjects();
      for(const d of state.downloads.filter(d=>d.status==='complete'&&!previousComplete.has(d.id))){
        previousComplete.add(d.id);if(!windowContext)toast(t('اكتمل التحميل: ','Download complete: ')+d.name);
        if(!state.desktop&&!windowContext&&state.settings.completionDialog&&!$('#dialog').open){if(!nativeTool('complete',{id:d.id}))showComplete(d.id);}
        if(!state.desktop&&state.settings.sounds)beep();
      }
      if(detailId&&$('#dialog').open)updateDetail();
      if(windowContext==='updates')renderUpdates();
    }
    const rate=state.downloads.reduce((n,d)=>n+d.speed,0);history.push(rate);if(history.length>60)history.shift();updateChart();if(typeof updatePowerLive==='function')updatePowerLive();
    const c=$('#connection-state');if(c)c.classList.remove('offline');
  }catch(e){const c=$('#connection-state');if(c){c.classList.add('offline');c.innerHTML=`<span class="dot"></span>${t('الاتصال منقطع','Disconnected')}`;}
    if(!initialized){$('#main').innerHTML=`<div class="empty"><h1>Flow</h1><p>${h(messageText(e.message))}</p><p>${t('شغّل التطبيق بواسطة npm start أو npm run web.','Run the app with npm start or npm run web.')}</p>${button('retry',t('إعادة الاتصال','Reconnect'),'refresh')}</div>`;}
  }finally{polling=false;}
}
function baseDownloads(){if(view.startsWith('saved:'))return state.downloads.filter(d=>FlowLibraryModel.matches(d,state.library?.views.find(v=>v.id===view.slice(6))?.query||''));return state.downloads.filter(d=>view==='all'||view==='active'&&isActive(d)||view==='complete'&&d.status==='complete'||view==='unfinished'&&d.status!=='complete'||view.startsWith('queue:')&&d.queueId===view.slice(6)||d.category===view);}
function filteredDownloads(){return baseDownloads().filter(d=>(filter==='all'||filter==='active'&&isActive(d)||filter==='complete'&&d.status==='complete'||filter==='paused'&&['paused','limited'].includes(d.status)||filter==='pending'&&d.status==='pending'||filter==='queued'&&d.status==='queued'||filter==='error'&&d.status==='error')&&(!search||FlowLibraryModel.matches(d,search))).sort((a,b)=>{const x=sort==='time'?((a.size-a.downloaded)/(a.speed||1)):a[sort],y=sort==='time'?((b.size-b.downloaded)/(b.speed||1)):b[sort];return (typeof x==='number'?x-y:String(x).localeCompare(String(y)))*(sortAsc?1:-1);});}
function updateChart(){const target=$('#speed-chart');if(!target)return;const max=Math.max(1024,...history),values=Array(60-history.length).fill(0).concat(history);const points=values.map((n,i)=>`${i/59*600},${58-n/max*50}`).join(' ');target.innerHTML=`<svg viewBox="0 0 600 65" preserveAspectRatio="none" aria-label="${t('سرعة التحميل الفعلية','Actual transfer speed')}"><path d="M0 16h600M0 38h600M0 60h600" stroke="var(--line)" fill="none" stroke-dasharray="4 5"/><polygon points="0,65 ${points} 600,65" fill="var(--primary-soft)"/><polyline points="${points}" fill="none" stroke="var(--primary)" stroke-width="1.7" vector-effect="non-scaling-stroke"/></svg>`;$('#chart-current').textContent=' · '+size(history.at(-1)||0)+'/s';}
function modal(title,body,foot='',wide=false){detailId=null;const dlg=$('#dialog');dlg.className=wide?'wide':'';$('#dialog-content').innerHTML=`<div class="modal-head"><h2>${h(title)}</h2>${ib('close',t('إغلاق','Close'),'x')}</div>${body}<div class="modal-foot">${foot||button('close',t('إغلاق','Close'),null)}</div>`;if(!dlg.open)dlg.showModal();}
function closeModal(){detailId=null;settingsDraft=null;$('#dialog').close();}
function field(name,label,value='',type='text',help='',extra=''){return `<div class="field"><label for="f-${name}">${h(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${h(value)}" ${extra}>${help?`<small>${help}</small>`:''}</div>`;}
function select(name,label,values,current){return `<div class="field"><label for="f-${name}">${h(label)}</label><select id="f-${name}" name="${name}">${Object.entries(values).map(([v,l])=>`<option value="${h(v)}" ${String(current)===v?'selected':''}>${h(l)}</option>`).join('')}</select></div>`;}
function check(name,label,value,help=''){return `<label class="check-field"><input name="${name}" type="checkbox" ${value?'checked':''}><span>${h(label)}${help?`<small>${help}</small>`:''}</span></label>`;}
function formError(e){const target=$('#form-error');if(target)target.textContent=messageText(e.message||e);else toast(e.message||e,true);}
function readForm(selector){const form=$(selector),out={};for(const el of form.querySelectorAll('[name]')){if(el.disabled)continue;out[el.name]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;}return out;}
function openAdd(url=''){if(nativeTool('add',{url}))return;
  modal(t('إضافة تحميل جديد','Add a download'),`<div class="modal-body"><form id="add-form"><div id="form-error" class="form-error"></div>${field('url',t('رابط الملف','File URL'),url,'url','',`required dir="ltr" placeholder="https://example.com/file.zip"`)}<div class="field-row">${field('name',t('اسم الملف','File name'),'','text',t('اتركه فارغاً لاستخدام اسم الرابط','Leave blank to use the name from the URL'),'dir="ltr"')}${select('category',t('التصنيف','Category'),{'':t('تلقائي حسب الامتداد','Detect automatically'),...Object.fromEntries(Object.entries(catNames()).filter(([k])=>k!=='all'))},'')}</div><div class="field"><label>${t('مجلد الحفظ','Save to')}</label><div class="field-inline"><input name="directory" value="" placeholder="${h(state.settings.downloadDir)}" dir="ltr">${ib('browseAdd',t('اختيار مجلد','Choose folder'),'folder')}</div>${folderSuggestions()}</div><p class="help">${t('اترك المجلد فارغًا لتطبيق قواعد التنظيم أو مجلد التصنيف الافتراضي.','Leave folder blank to use automation rules or the default category folder.')}</p>${select('queueId',t('قائمة الانتظار','Queue'),Object.fromEntries(state.queues.map(q=>[q.id,q.name])),'main')}${field('description',t('ملاحظات','Description'))}<div id="probe-result"></div><div id="video-qualities"></div><details><summary>${t('خيارات متقدمة','Advanced options')}</summary><div class="field-row">${field('username',t('اسم المستخدم','Username'))}${field('password',t('كلمة المرور','Password'),'','password')}</div>${field('referer',t('صفحة المصدر (Referer)','Source page (Referer)'),'','url','','dir="ltr"')}${field('cookie',t('Cookie للطلب المصرح به','Cookie for an authorized request'),'','password')}${field('speedLimit',t('حد سرعة هذا الملف KB/s','File speed limit in KB/s'),0,'number',t('0 = بدون حد','0 = unlimited'),'min="0"')}${select('priority',t('الأولوية','Priority'),{'':t('تلقائي من القواعد','Automatic from rules'),...priorityOptions()},'')}${select('mode',t('نوع التحميل','Download mode'),{file:t('ملف مباشر','Direct file'),site:t('فيديو من صفحة موقع / YouTube','Website / YouTube video'),media:t('بث HLS / DASH غير مشفر','Unencrypted HLS / DASH stream')},'file')}${field('audioURL',t('رابط مسار الصوت المنفصل (اختياري)','Separate audio URL (optional)'),'','url','','dir="ltr"')}${select('format',t('صيغة إخراج الوسائط','Media output format'),{mp4:'MP4',mkv:'MKV'},'mp4')}</details></form></div>`,`${button('probeAdd',t('فحص الرابط / جودات الفيديو','Inspect link / video quality'),'eye')}${button('addLater',t('تحميل لاحقاً','Download later'),'clock')}${button('addNow',t('بدء التحميل','Start download'),'arrow','primary')}`);
  if(windowContext==='download-info'){const item=state.downloads.find(d=>d.id===windowArgs.get('id'));if(item){const values={url:item.url,name:item.name,directory:item.directory,category:item.category,queueId:item.queueId,description:item.description,mode:JSON.parse(item.meta).mode,speedLimit:JSON.parse(item.meta).speedLimit||0,priority:JSON.parse(item.meta).priority||0};for(const [k,v]of Object.entries(values)){const field=$('#add-form [name="'+k+'"]');if(field)field.value=v??'';}$('#probe-result').innerHTML=`<div class="info-box">${item.size?size(item.size):t('الحجم غير معروف','Unknown size')} · ${t('الاستئناف:','Resume:')} ${item.resumable?t('نعم','Yes'):t('لا','No')}</div>`;}}$('#add-form').addEventListener('input',e=>{if(e.target.name==='directory')$('#add-form').dataset.directoryEdited='1';});$('#add-form').addEventListener('change',e=>{if(e.target.name==='queueId')$('#add-form').dataset.queueEdited='1';});$('#add-form').addEventListener('submit',e=>{e.preventDefault();submitAdd(false);});setTimeout(()=>$('#f-url')?.focus(),50);
}
async function submitAdd(later){
  const form=$('#add-form');if(!form.reportValidity())return;const d=readForm('#add-form');if(isPlaylistURL(d.url)){openPower('playlists',d.url);return;}if(windowContext!=='download-info'&&state.settings.preventDuplicates&&!d.duplicateMode){const duplicates=await api('duplicateCheck',{url:d.url});if(duplicates.length){const old=$('#add-duplicates');if(!old){const box=document.createElement('div');box.id='add-duplicates';box.className='info-box';box.innerHTML='<p>'+t('الرابط موجود بالفعل. اختر التصرف ثم اضغط إضافة.','This URL is already in your library. Choose an action, then submit again.')+'</p>'+select('duplicateMode',t('عند التكرار','Duplicate action'),{reuse:t('استخدام التحميل الموجود','Use existing task'),allow:t('إنشاء نسخة أخرى','Create another copy')},'reuse');form.append(box);}return;}}if(windowContext!=='download-info'){if(!form.dataset.directoryEdited)delete d.directory;if(!form.dataset.queueEdited)delete d.queueId;}
  const submit=$$('[data-action="addNow"],[data-action="addLater"]');submit.forEach(b=>b.disabled=true);
  try{const headers={};if(d.username||d.password){const bytes=new TextEncoder().encode(d.username+':'+d.password);headers.authorization='Basic '+btoa(String.fromCharCode(...bytes));}if(d.referer)headers.referer=d.referer;if(d.cookie)headers.cookie=d.cookie;
    if(windowContext==='download-info')await api('confirmDownload',{...d,id:windowArgs.get('id'),headers,later});else{const result=await api('add',{...d,headers,later});if(d.duplicateMode==='reuse'){if(!later&&result.status!=='complete')await api('start',{id:result.id});if(window.desktopAPI)await api('window',{kind:result.status==='pending'?'download-info':'details',id:result.id});}}closeModal();toast(t('تمت إضافة التحميل','Download added'));await refresh();
  }catch(e){formError(e);submit.forEach(b=>b.disabled=false);}
}
function openBatch(){if(nativeTool('batch'))return;modal(t('تحميل دفعي','Batch download'),`<div class="modal-body"><form id="batch-form"><div id="form-error" class="form-error"></div><div class="field"><label>${t('الروابط (رابط واحد في كل سطر)','URLs (one per line)')}</label><textarea name="urls" rows="7" dir="ltr" placeholder="https://example.com/file-01.zip"></textarea></div><details><summary>${t('توليد تسلسل رقمي','Generate a numeric sequence')}</summary><p class="help">${t('ضع * مكان الرقم، مثل file-*.zip','Use * in place of the number, e.g. file-*.zip')}</p>${field('pattern',t('نمط الرابط','URL pattern'),'','text','','dir="ltr"')}<div class="field-row">${field('from',t('من','From'),1,'number','','min="0" max="999999"')}${field('to',t('إلى','To'),10,'number','','min="0" max="999999"')}</div>${field('digits',t('عدد خانات الرقم','Number padding'),2,'number','','min="1" max="8"')}${button('generateBatch',t('توليد الروابط','Generate URLs'),'list')}</details>${select('queueId',t('القائمة','Queue'),Object.fromEntries(state.queues.map(q=>[q.id,q.name])),'main')}${check('start',t('تشغيل القائمة بعد الإضافة','Start queue after adding'),false)}</form></div>`,`${button('close',t('إلغاء','Cancel'),null)}${button('saveBatch',t('إضافة الروابط','Add URLs'),'plus','primary')}`);}
function confirmDelete(ids){const files=state.downloads.filter(d=>ids.includes(d.id));modal(t('حذف التحميلات','Remove downloads'),`<div class="modal-body"><p>${t('حذف الملفات المحددة من قائمة التحميلات؟','Remove the selected downloads from the list?')}</p><div class="info-box">${files.map(d=>h(d.name)).join('<br>')}</div>${check('deleteFile',t('حذف الملفات المكتملة من القرص أيضاً','Also delete completed files from disk'),false)}<p class="help">${t('بدون حذف الملف من القرص، ينتقل التحميل وأجزاؤه إلى سلة الاسترجاع.','Without deleting the disk file, the task and its partial data move to the recovery bin.')}</p></div>`,`${button('close',t('إلغاء','Cancel'),null)}${button('confirmDelete',t('حذف','Remove'),'trash','danger',`data-ids="${ids.join(',')}"`)}`);}
function renderQueuePage(){const q=state.queues.find(q=>q.id===queueId)||state.queues[0];queueId=q.id;const sched=JSON.parse(q.schedule);
  $('#main').innerHTML=`<div class="page-heading"><div><div class="eyebrow">ON YOUR SCHEDULE</div><h1>${t('قوائم الانتظار','Download queues')}</h1><p class="subtitle">${t('رتّب ملفاتك وحدّد الوقت المناسب لتحميلها.','Organize your files and choose when they download.')}</p></div>${button('newQueue',t('قائمة جديدة','New queue'),'plus','primary')}</div><div class="queue-layout"><section class="panel queue-list">${state.queues.map(item=>`<button class="queue-card ${item.id===q.id?'active':''}" data-queue="${item.id}">${icon('list')}<div><strong>${h(item.name)}</strong><small>${state.downloads.filter(d=>d.queueId===item.id&&d.status!=='complete').length} ${t('ملفات متبقية','files remaining')} · ${item.running?t('تعمل الآن','Running'):t('متوقفة','Stopped')}</small></div></button>`).join('')}</section><section class="panel queue-form"><form id="queue-form"><div id="form-error" class="form-error"></div><div class="field-row">${field('name',t('اسم القائمة','Queue name'),q.name)}${field('simultaneous',t('تحميلات متزامنة','Simultaneous downloads'),q.simultaneous,'number','','min="1" max="16"')}</div>${field('bandwidthKB',t('حد سرعة القائمة مجتمعة KB/s · صفر بلا حد','Queue shared speed KB/s · 0 unlimited'),sched.bandwidthKB||0,'number','','min="0" max="1000000"')}${check('enabled',t('تفعيل الجدولة','Enable scheduling'),sched.enabled)}<div class="field-row">${field('start',t('بدء التحميل في','Start at'),sched.start||'23:00','time')}${field('stop',t('إيقاف التحميل في (اختياري)','Stop at (optional)'),sched.stop||'','time')}</div>${field('date',t('تاريخ محدد (اتركه فارغاً للتكرار)','Specific date (blank for recurring)'),sched.date||'','date')}<h3>${t('أيام التكرار','Repeat on')}</h3><div class="weekday-list">${[t('الأحد','Sun'),t('الاثنين','Mon'),t('الثلاثاء','Tue'),t('الأربعاء','Wed'),t('الخميس','Thu'),t('الجمعة','Fri'),t('السبت','Sat')].map((label,i)=>`<label class="weekday"><input name="day-${i}" type="checkbox" ${!sched.days?.length||sched.days.includes(i)?'checked':''}>${label}</label>`).join('')}</div>${select('completion',t('عند انتهاء القائمة','When the queue finishes'),{none:t('لا إجراء','Do nothing'),quit:t('إغلاق تطبيق Electron','Quit Electron app')},sched.completion||'none')}<div class="info-box">${icon('info')} ${t('تعمل الجدولة أثناء فتح التطبيق وفق توقيت الجهاز. لا توقظ الجهاز من السكون.','Schedules run while the app is open, in your computer’s time zone. They do not wake a sleeping computer.')}</div><div class="actions">${button('saveQueue',t('حفظ الجدول','Save schedule'),'check','primary')}${button(q.running?'stopQueue':'startQueue',q.running?t('إيقاف القائمة','Stop queue'):t('تشغيل الآن','Start now'),q.running?'pause':'play')}${button('viewQueue',t('عرض الملفات','View files'),'list')}${q.id!=='main'?button('removeQueue',t('حذف القائمة','Delete queue'),'trash','danger'):''}</div></form></section></div>`;
}
async function saveQueue(){const d=readForm('#queue-form'),q=state.queues.find(q=>q.id===queueId);const days=Array.from({length:7},(_,i)=>i).filter(i=>d['day-'+i]);if(!days.length){formError(t('اختر يوماً واحداً على الأقل','Choose at least one day'));return;}
  try{await api('queue',{id:q.id,name:d.name,simultaneous:d.simultaneous,bandwidthKB:d.bandwidthKB,schedule:{...JSON.parse(q.schedule),enabled:d.enabled,start:d.start,stop:d.stop,date:d.date,days,completion:d.completion}});toast(t('تم حفظ الجدول','Schedule saved'));await refresh();}catch(e){formError(e);}}
function renderGrabber(){if(nativeTool('grabber'))return;$('#main').innerHTML=`<div class="page-heading"><div><div class="eyebrow">A LITTLE WEB, OFFLINE</div><h1>${t('ساحب المواقع','Site grabber')}</h1><p class="subtitle">${t('اكتشف الروابط، اختر ملفاتك، واحفظ نسخة للتصفح دون اتصال.','Discover links, choose your files, and save them for offline browsing.')}</p></div>${button('newGrab',t('مشروع جديد','New project'),'plus','primary')}</div><div id="projects" class="project-grid"></div>`;renderProjects();}
const projectStatus=s=>({scanning:t('جارٍ استكشاف الموقع','Exploring website'),ready:t('جاهز للاختيار','Ready to select'),downloading:t('جارٍ التحميل','Downloading'),complete:t('مكتمل دون اتصال','Saved for offline use'),partial:t('اكتمل جزئياً','Partially downloaded'),cancelled:t('تم إيقاف الفحص','Scan cancelled'),error:t('تعذر الفحص','Scan failed')})[s]||s;
