function openGrab(){modal(t('مشروع سحب موقع','New site project'),`<div class="modal-body"><form id="grab-form"><div id="form-error" class="form-error"></div>${field('name',t('اسم المشروع','Project name'))}${field('url',t('رابط البداية','Starting URL'),'','url','','dir="ltr" required')}${select('template',t('قالب المشروع','Template'),{offline:t('تصفح دون اتصال','Offline browsing'),images:t('صور الموقع','Images'),audio:t('صوتيات','Audio'),archives:t('ملفات مضغوطة','Archives'),custom:t('مخصص','Custom')},'offline')}<div class="field-row">${field('depth',t('عمق الروابط','Link depth'),1,'number','','min="0" max="4"')}${field('maxPages',t('الحد الأقصى للصفحات','Maximum pages'),30,'number','','min="1" max="200"')}</div>${field('extensions',t('امتدادات الملفات (فارغ = جميع الأنواع)','File extensions (blank = all types)'),'','text',t('مثال: jpg png webp pdf','Example: jpg png webp pdf'),'dir="ltr"')}${check('includeHTML',t('تضمين صفحات HTML وتحويل الروابط لمحلية','Include HTML pages and rewrite links for offline use'),true)}${check('external',t('السماح بروابط من نطاقات خارجية','Allow links from other domains'),false)}${check('noParent',t('عدم استكشاف المجلدات الأعلى','Do not explore parent directories'),true)}<div class="info-box">${t('يفحص HTML الثابت. الصفحات التي تتطلب تنفيذ JavaScript أو تسجيل دخول تفاعلي تحتاج معالجة إضافية. الحد الأقصى للصفحة 5 MB.','Scans static HTML. Pages that require JavaScript execution or interactive sign-in need additional handling. Maximum page size: 5 MB.')}</div></form></div>`,`${button('close',t('إلغاء','Cancel'),null)}${button('scanGrab',t('استكشاف الموقع','Explore site'),'globe','primary')}`);}
function showProject(id){const p=state.projects.find(p=>p.id===id);if(!p)return;const d=JSON.parse(p.data);modal(p.name,`<div class="modal-body"><div class="info-box">${projectStatus(d.status)} · ${d.visited} ${t('صفحة تم فحصها','pages explored')} · ${d.links.length} ${t('رابط','links')}</div><div class="actions" style="margin-bottom:15px">${button('checkProjectAll',t('تحديد الكل','Select all'),'check')}${button('uncheckProjectAll',t('إلغاء التحديد','Unselect all'),null)}${check('hideHTML',t('إخفاء صفحات HTML','Hide HTML pages'),false)}</div><div class="inline-table"><table><thead><tr><th></th><th>${t('اسم الملف / الرابط','File name / URL')}</th><th>${t('النوع','Type')}</th></tr></thead><tbody>${d.links.map(l=>`<tr data-kind="${l.kind}"><td><input type="checkbox" data-project-url="${h(l.url)}" checked aria-label="${h(l.name)}"></td><td><span class="file-name" style="max-width:650px">${h(l.name)}</span><span class="file-sub" style="max-width:650px">${h(l.url)}</span></td><td>${l.kind==='html'?'HTML':t('ملف','File')}</td></tr>`).join('')}</tbody></table></div><div id="form-error" class="form-error"></div>${d.root?`<div class="info-box break" dir="ltr">${h(d.root)}</div>`:''}</div>`,`${button('close',t('إغلاق','Close'),null)}${button('downloadProject',t('تحميل المحدد','Download selected'),'arrow','primary',`data-id="${id}" ${d.status==='scanning'||d.mapping?'disabled':''}`)}`,true);}
async function renderLogs(){if(nativeTool('logs'))return;$('#main').innerHTML=`<div class="page-heading"><div><div class="eyebrow">EVERY LITTLE DETAIL</div><h1>${t('سجل النشاط','Activity log')}</h1><p class="subtitle">${t('عمليات التحميل والمحاولات والأحداث المحلية.','Downloads, retries, and local events.')}</p></div><div class="actions">${button('diagnostics',t('تقرير فحص','Diagnostic report'),'activity')}${button('refreshLogs',t('تحديث','Refresh'),'refresh')}</div></div><section class="panel" id="log-list"><div class="empty">${t('جارٍ القراءة...','Loading...')}</div></section>`;try{const logs=await api('logs');if($('#log-list'))$('#log-list').innerHTML=logs.length?logs.map(e=>`<div class="log-row"><span class="muted">${date(e.time)} · ${new Date(e.time).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}</span><span class="${e.type==='error'?'':'green'}">${h(e.type)}</span><span class="break">${h(messageText(e.message))}</span></div>`).join(''):`<div class="empty">${t('سيظهر نشاطك هنا عند بدء الاستخدام.','Your activity will appear here.')}</div>`;}catch(e){toast(e.message,true);}}
const settingTabs=()=>({general:t('عام','General'),types:t('أنواع الملفات','File types'),connection:t('الاتصال','Connection'),save:t('الحفظ في','Save to'),downloads:t('التحميلات','Downloads'),proxy:t('الوكيل / SOCKS','Proxy / SOCKS'),logins:t('حسابات المواقع','Site logins'),vpn:t('اتصال VPN','Dial Up / VPN'),sounds:t('الأصوات','Sounds')});
function captureSettings(){const form=$('#settings-form');if(!form||!settingsDraft)return;const values=readForm('#settings-form');for(const[k,v]of Object.entries(values))if(!k.startsWith('cat-'))settingsDraft[k]=v;else{settingsDraft.categoryFolders||={};settingsDraft.categoryFolders[k.slice(4)]=v;}}
