function settingsContent(s){switch(settingsTab){
 case'general':return `${select('language',t('لغة الواجهة','Interface language'),{ar:'العربية',en:'English'},s.language)}${select('theme',t('المظهر','Appearance'),{system:t('حسب النظام','System'),light:t('فاتح','Light'),dark:t('داكن','Dark')},s.theme)}${field('textScale',t('حجم النص %','Text scale %'),s.textScale,'number','','min="80" max="150"')}${check('startAtLogin',t('تشغيل Flow مع بدء النظام','Launch Flow when the computer starts'),s.startAtLogin)}${check('preventDuplicates',t('تنبيه عند تكرار الروابط وإعادة استخدام التحميل من المتصفح','Warn on duplicate URLs and reuse browser tasks'),s.preventDuplicates)}${check('preventSleep',t('منع سكون الجهاز أثناء التحميل','Keep the computer awake while downloading'),s.preventSleep)}${check('integration',t('تفعيل تكامل المتصفح','Enable browser integration'),s.integration)}${check('monitorClipboard',t('مراقبة روابط الحافظة','Watch clipboard for file links'),s.monitorClipboard,t('متاح داخل Electron فقط','Available in Electron only'))}${check('videoPanel',t('إظهار لوحة تحميل الفيديو في الإضافة','Show extension video panel'),s.videoPanel)}${select('panelMode',t('حجم لوحة الفيديو','Video panel size'),{full:t('كامل','Full'),mini:t('مصغر','Mini')},s.panelMode)}<div class="info-box">${t('لربط كروم، افتح «المتصفح» من شريط الأدوات وجهّز الربط، ثم فعّل الإضافة مرة واحدة.','Open Browser in the toolbar, set up the connection, then enable the extension once.')}</div>`;
 case'types':return `<div class="field"><label>${t('امتدادات الالتقاط التلقائي','Automatically captured extensions')}</label><textarea name="fileTypes" rows="5" dir="ltr">${h(s.fileTypes)}</textarea><small>${t('افصل بين الامتدادات بمسافة، بدون نقطة.','Separate extensions with spaces, without a dot.')}</small></div><div class="field"><label>${t('المواقع المستثناة (نطاق في كل سطر)','Excluded sites (one host per line)')}</label><textarea name="excludedSites" dir="ltr">${h(s.excludedSites)}</textarea></div><div class="info-box">${t('الإضافة تقرأ هذه الإعدادات عند المزامنة من نافذتها. زر Alt عند النقر يمنع الالتقاط، وCtrl + Shift يفرض الالتقاط.','Sync these settings from the extension popup. Alt bypasses capture; Ctrl + Shift forces capture.')}</div>`;
 case'connection':return `<div class="field-row">${field('connections',t('أقصى اتصالات لكل ملف','Maximum connections per file'),s.connections,'number','','min="1" max="32"')}${field('simultaneous',t('تحميلات متزامنة إجمالاً','Total simultaneous downloads'),s.simultaneous,'number','','min="1" max="16"')}</div><div class="field-row">${field('retries',t('محاولات إعادة الاتصال','Retry attempts'),s.retries,'number','','min="0" max="30"')}${field('retryDelay',t('فاصل المحاولة بالثواني','Retry delay in seconds'),s.retryDelay,'number','','min="0.1" max="60" step="0.1"')}</div>${field('speedLimit',t('حد السرعة الإجمالي KB/s','Global speed limit KB/s'),s.speedLimit,'number',t('0 = بلا حد. يطبق على HTTP / HTTPS.','0 = unlimited. Applies to HTTP / HTTPS.'),'min="0"')}<h3>${t('حصة البيانات','Data quota')}</h3><div class="field-row">${field('quotaMB',t('الحد MB (0 = معطل)','Limit MB (0 = disabled)'),s.quotaMB,'number','','min="0" step="0.1"')}${field('quotaHours',t('تجديد كل (ساعات)','Reset every (hours)'),s.quotaHours,'number','','min="0.01" step="0.01"')}</div><div class="field"><label>${t('استثناءات الخوادم: نطاق=اتصالات في كل سطر','Server exceptions: host=connections per line')}</label><textarea name="serverRules" dir="ltr">${h(Object.entries(s.serverConnections||{}).map(([k,v])=>k+'='+v).join('\n'))}</textarea></div>`;
 case'save':return `<div class="field"><label>${t('المجلد الافتراضي','Default download folder')}</label><div class="field-inline"><input name="downloadDir" dir="ltr" value="${h(s.downloadDir)}">${ib('browseSetting',t('اختيار مجلد','Choose folder'),'folder','data-field="downloadDir"')}</div></div><div class="field"><label>${t('مجلد الأجزاء المؤقتة','Temporary segments folder')}</label><div class="field-inline"><input name="tempDir" dir="ltr" value="${h(s.tempDir)}">${ib('browseSetting',t('اختيار مجلد','Choose folder'),'folder','data-field="tempDir"')}</div></div><h3>${t('مجلدات التصنيفات','Category folders')}</h3>${Object.entries(catNames()).filter(([k])=>k!=='all').map(([k,label])=>field('cat-'+k,label,s.categoryFolders?.[k]||s.downloadDir,'text','','dir="ltr"')).join('')}<div class="info-box">${t('أوقف جميع التحميلات قبل تغيير المجلدات. الأجزاء السابقة تظل في مكانها؛ لا تغيّر مجلد الأجزاء مع وجود ملفات تحتاج استئنافاً.','Pause all downloads before changing folders. Existing partial data stays in its original folder; keep that folder while resumable downloads exist.')}</div>`;
 case'downloads':return `${check('showProgress',t('فتح نافذة تقدم مستقلة عند بدء التحميل','Open a separate progress window when a download starts'),s.showProgress)}${check('browserConfirm',t('عرض معلومات الملف قبل تنزيله من المتصفح','Show file information before browser downloads'),s.browserConfirm)}${check('completionDialog',t('إظهار نافذة عند اكتمال التحميل','Show download completion dialog'),s.completionDialog)}${check('ignoreModified',t('تجاهل تغير Last-Modified عند الاستئناف','Ignore Last-Modified changes when resuming'),s.ignoreModified,t('يبقى فحص الحجم وETag فعالاً للحفاظ على سلامة الملف.','Size and ETag checks remain active to protect file integrity.'))}${field('userAgent','User-Agent',s.userAgent,'text','','dir="ltr"')}<h3>${t('فحص خارجي بعد التحميل','External post-download scanner')}</h3>${field('scanner',t('مسار البرنامج التنفيذي','Executable path'),s.scanner,'text','','dir="ltr"')}${field('scannerArgs',t('المعاملات (JSON array أو [File])','Arguments (JSON array or [File])'),s.scannerArgs,'text',t('مثال: ["--scan", "[File]"]، دون أوامر shell.','Example: ["--scan", "[File]"], no shell commands.'),'dir="ltr"')}<div class="info-box">${t('لا يبدأ تحميل خفي أثناء تحرير معلومات الملف. يبدأ بعد ضغط «بدء التحميل» فقط.','Downloads start only after you press Start download.')}</div>`;
 case'proxy':return `${field('proxy',t('عنوان HTTP / SOCKS proxy','HTTP / SOCKS proxy URL'),s.proxy,'text',t('مثال: socks5://127.0.0.1:1080 — فارغ لاتصال مباشر','Example: socks5://127.0.0.1:1080 — blank for direct connection'),'dir="ltr"')}${field('proxyExceptions',t('نطاقات مستثناة، مفصولة بفاصلة','Excluded hosts, comma-separated'),s.proxyExceptions,'text','','dir="ltr"')}<div class="info-box">${t('الوكيل يطبق على HTTP / HTTPS. FTP يستخدم اتصال PASV مباشر. الوكيل الخاص بالنظام وNTLM / Kerberos غير مدمجين.','Proxy applies to HTTP / HTTPS. FTP uses a direct PASV connection. System proxy, NTLM, and Kerberos are not integrated.')}</div>`;
 case'logins':return `<div class="info-box green">${icon('shield')} ${t('بيانات الحسابات مشفّرة محلياً. لن تُصدّر كلمات المرور.','Credentials are encrypted locally. Passwords are excluded from exports.')}</div><div class="inline-table"><table><tbody>${state.logins.map(l=>`<tr><td dir="ltr">${h(l.host)}</td><td>${h(l.username)}</td><td>${ib('removeLogin',t('حذف الحساب','Remove login'),'trash',`data-host="${h(l.host)}"`)}</td></tr>`).join('')||`<tr><td>${t('لا توجد حسابات محفوظة','No saved logins')}</td></tr>`}</tbody></table></div>${field('loginHost',t('النطاق (بدون https://)','Host (without https://)'),'','text','','dir="ltr"')}${field('loginUsername',t('اسم المستخدم','Username'))}${field('loginPassword',t('كلمة المرور','Password'),'','password')}${button('addLogin',t('حفظ الحساب','Save login'),'plus')}<p class="help">${t('هذه العملية تحفظ الحساب مباشرة. تستخدم مصادقة Basic أو FTP للنطاق المطابق فقط.','Saving here applies immediately. Uses Basic or FTP authentication for the exact host only.')}</p>`;
 case'vpn':return `${field('vpnName',t('اسم اتصال ويندوز المحفوظ','Saved Windows connection name'),s.vpnName)}<div class="actions">${button('vpnConnect',t('اتصال','Connect'),'link')}${button('vpnDisconnect',t('قطع الاتصال','Disconnect'),'x')}</div><div class="info-box">${t('يستخدم rasdial لاتصال محفوظ مسبقاً في ويندوز. لا يخزن كلمات مرور VPN، ولا يوقف تشغيل الجهاز. إعادة المحاولة التلقائية للمودم غير مدمجة.','Uses rasdial for an existing Windows connection. Does not store VPN passwords or shut down the computer. Automatic modem redial is not integrated.')}</div>`;
 case'sounds':return `${check('sounds',t('تفعيل أصوات الأحداث','Enable event sounds'),s.sounds)}${[['soundComplete',t('اكتمال تحميل','Download complete')],['soundError',t('فشل التحميل','Download failure')],['soundQueue',t('انتهاء قائمة الانتظار','Queue finished')]].map(([name,label])=>`<div class="field"><label>${label}</label><div class="field-inline"><input name="${name}" value="${h(s[name])}" dir="ltr" placeholder="C:\Sounds\notify.wav">${ib('browseSound',t('اختيار WAV','Choose WAV'),'folder',`data-field="${name}"`)}${ib('playSound',t('تشغيل','Play'),'volume',`data-field="${name}"`)}</div></div>`).join('')}<div class="info-box">${t('الأصوات المحلية تحتاج Electron. يستخدم المتصفح نغمة قصيرة عند الاكتمال بعد تفاعلك مع الصفحة.','Local sounds require Electron. The browser plays a short completion tone after you interact with the page.')}</div>`;
 }}
async function saveSettings(){captureSettings();try{
  if(settingsDraft.serverRules!==undefined){const rules={};for(const line of settingsDraft.serverRules.split('\n').filter(s=>s.trim())){const m=/^([^=\s]+)\s*=\s*(\d+)$/.exec(line.trim());if(!m)throw Error(t('صيغة استثناء الخادم غير صحيحة','Invalid server exception'));rules[m[1]]=Number(m[2]);}settingsDraft.serverConnections=rules;delete settingsDraft.serverRules;}
  const payload={...settingsDraft};delete payload.loginHost;delete payload.loginUsername;delete payload.loginPassword;
  await api('settings',payload);closeModal();await refresh();renderShell();renderMain();toast(t('تم حفظ الإعدادات','Settings saved'));
}catch(e){formError(e);}}
function toast(message,error=false){message=messageText(message);const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=`${icon(error?'info':'check')}<span>${h(message)}</span><button aria-label="Close">${icon('x')}</button>`;el.querySelector('button').onclick=()=>el.remove();const container=$('#toasts');while(container.children.length>=2)container.firstElementChild.remove();container.append(el);setTimeout(()=>el.remove(),error?7000:3500);}
let audioCtx;function beep(){try{audioCtx||=new AudioContext();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.connect(gain);gain.connect(audioCtx.destination);osc.frequency.setValueAtTime(660,audioCtx.currentTime);osc.frequency.setValueAtTime(880,audioCtx.currentTime+.12);gain.gain.setValueAtTime(.06,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.35);osc.start();osc.stop(audioCtx.currentTime+.35);}catch{}}
async function downloadJSON(data,prefix='Flow-backup'){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=prefix+'-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
async function handleAction(name,el){const id=el.dataset.id;
 switch(name){
  case'close':if($('[name="hideComplete"]')?.checked)await action('settings',{completionDialog:false});closeModal();break;
  case'retry':await refresh();break;
  case'add':openAdd();break;case'addNow':await submitAdd(false);break;case'addLater':await submitAdd(true);break;
  case'browseAdd':{const dir=await action('chooseDirectory');if(dir){$('[name="directory"]').value=dir;$('#add-form').dataset.directoryEdited='1';}break;}
  case'probeAdd':{const url=$('#f-url').value;if(!url)return;if(isPlaylistURL(url)){openPower('playlists',url);break;}el.disabled=true;$('#probe-result').innerHTML=`<div class="info-box">${t('جارٍ فحص الرابط وقراءة معلوماته…','Inspecting the URL and reading its details…')}</div>`;try{const d=readForm('#add-form'),headers={};if(d.referer)headers.referer=d.referer;if(d.cookie)headers.cookie=d.cookie;if(d.username||d.password)headers.authorization='Basic '+btoa(String.fromCharCode(...new TextEncoder().encode(d.username+':'+d.password)));const info=await api('probe',{url,headers,mode:d.mode,id:windowArgs.get('id')||undefined});if(info.video){showVideoQualities(info);el.disabled=false;break;}$('#probe-result').innerHTML=`<div class="info-box green">${size(info.size)} · ${info.type} · ${t('الاستئناف:','Resume:')} ${info.resumable?t('نعم','Yes'):t('لا','No')}${/\.zip(\?|$)/i.test(url)?' '+button('zipPreview',t('معاينة الأرشيف','Preview archive'),'archive'):''}</div>`;}catch(e){formError(e);}el.disabled=false;break;}
  case'zipPreview':{try{const files=await api('zip',{url:$('#f-url').value});$('#probe-result').innerHTML=`<div class="inline-table"><table><tbody>${files.map(f=>`<tr><td dir="ltr">${h(f.name)}</td><td>${size(f.size)}</td></tr>`).join('')}</tbody></table></div>`;}catch(e){formError(e);}break;}
  case'batch':openBatch();break;
  case'generateBatch':{const d=readForm('#batch-form');if(!d.pattern.includes('*')||d.to<d.from||d.to-d.from>=500){formError(t('أدخل نمطاً يحتوي * ومدى لا يتجاوز 500 رابط','Use a * pattern and a range of at most 500 URLs'));break;}$('[name="urls"]').value=Array.from({length:d.to-d.from+1},(_,i)=>d.pattern.replaceAll('*',String(d.from+i).padStart(Math.max(1,Math.min(8,d.digits)),'0'))).join('\n');break;}
  case'saveBatch':{const d=readForm('#batch-form'),urls=d.urls.split('\n').map(s=>s.trim()).filter(Boolean);if(!urls.length){formError(t('أدخل رابطاً واحداً على الأقل','Enter at least one URL'));break;}try{await api('batch',{urls,queueId:d.queueId});if(d.start)await api('queue',{id:d.queueId,running:true});closeModal();await refresh();toast(`${urls.length} ${t('تحميلات تمت إضافتها','downloads added')}`);}catch(e){formError(e);}break;}
  case'pause':case'start':await action(name,{id});break;
  case'pauseAll':await action(name,{},t('تم إيقاف التحميلات والقوائم','Downloads and queues paused'));break;
  case'detail':openDetail(id);break;
  case'detailToggle':{const d=state.downloads.find(d=>d.id===id);await action(d.status==='complete'?'folder':isActive(d)?'pause':'start',{id});break;}
  case'saveDetail':{try{const d=readForm('#detail-form');await api('update',{id,...d});closeModal();await refresh();toast(t('تم الحفظ','Saved'));}catch(e){formError(e);}break;}
  case'delete':confirmDelete([id]);break;
  case'confirmDelete':{el.disabled=true;const ids=el.dataset.ids.split(',');for(const item of ids)await action('remove',{id:item,deleteFile:$('[name="deleteFile"]').checked});selected.clear();closeModal();await refresh();break;}
  case'redownload':{modal(t('إعادة التحميل','Redownload'),`<div class="modal-body"><p>${t('البدء من جديد؟ سيُحذف تقدم الملف غير المكتمل. تبقى النسخة المكتملة إن وجدت.','Start again? Partial progress will be removed. An existing completed file is kept.')}</p></div>`,`${button('close',t('إلغاء','Cancel'),null)}${button('confirmRedownload',t('بدء جديد','Start again'),'refresh','primary',`data-id="${id}"`)}`);break;}
  case'confirmRedownload':closeModal();await action('redownload',{id});break;
  case'folder':case'open':await action(name,{id});break;
  case'clearComplete':modal(t('مسح السجلات المكتملة','Clear completed records'),`<div class="modal-body"><p>${t('إزالة سجلات التحميل المكتملة من القائمة؟ الملفات المحفوظة تبقى على القرص.','Remove completed downloads from the list? Saved files stay on disk.')}</p></div>`,`${button('close',t('إلغاء','Cancel'),null)}${button('confirmClear',t('مسح السجلات','Clear records'),'trash','danger')}`);break;
  case'confirmClear':await action('clearComplete');closeModal();break;
  case'export':{const data=await action('export');if(data)downloadJSON(data);break;}
  case'import':$('#import-file').click();break;
  case'prevPage':page=Math.max(1,page-1);updateDownloads();break;case'nextPage':page++;updateDownloads();break;
  case'theme':await action('settings',{theme:({system:'light',light:'dark',dark:'system'})[state.settings.theme]||'system'});renderShell();break;
  case'logs':navigate('logs');break;case'refreshLogs':renderLogs();break;
  case'unselect':selected.clear();updateDownloads();break;
  case'selectedStart':case'selectedPause':for(const item of selected)await action(name==='selectedStart'?'start':'pause',{id:item});break;
  case'selectedDelete':confirmDelete([...selected]);break;
  case'selectedQueue':modal(t('نقل إلى قائمة','Move to queue'),`<div class="modal-body">${select('selectedQueue',t('القائمة','Queue'),Object.fromEntries(state.queues.map(q=>[q.id,q.name])),'main')}</div>`,`${button('close',t('إلغاء','Cancel'),null)}${button('confirmMove',t('نقل','Move'),'check','primary')}`);break;
  case'confirmMove':{const queue=$('[name="selectedQueue"]').value;for(const item of selected)await action('update',{id:item,queueId:queue});closeModal();break;}
  case'newQueue':modal(t('إنشاء قائمة','Create queue'),`<div class="modal-body">${field('queueName',t('اسم القائمة','Queue name'))}<div id="form-error" class="form-error"></div></div>`,`${button('close',t('إلغاء','Cancel'),null)}${button('createQueue',t('إنشاء','Create'),'plus','primary')}`);break;
  case'createQueue':{const name=$('[name="queueName"]').value.trim();if(!name){formError(t('أدخل اسم القائمة','Enter a queue name'));break;}await action('queue',{name});closeModal();renderQueues();break;}
  case'saveQueue':await saveQueue();break;
  case'startQueue':await saveQueue();await action('queue',{id:queueId,running:true});renderQueues();break;
  case'stopQueue':await action('queueStop',{id:queueId});renderQueues();break;
  case'viewQueue':navigate('queue:'+queueId);break;
  case'removeQueue':await action('queueRemove',{id:queueId});queueId='main';renderQueues();break;
  case'newGrab':openGrab();break;
  case'scanGrab':{if(!$('#grab-form').reportValidity())break;const d=readForm('#grab-form');try{await api('grab',d);closeModal();await refresh();renderProjects();}catch(e){formError(e);}break;}
  case'projectDetails':showProject(id);break;case'cancelGrab':await action('grabCancel',{id});break;
  case'checkProjectAll':case'uncheckProjectAll':$$('[data-project-url]').filter(c=>!c.closest('tr').classList.contains('hide')).forEach(c=>c.checked=name==='checkProjectAll');break;
  case'downloadProject':{const urls=$$('[data-project-url]:checked').filter(c=>!c.closest('tr').classList.contains('hide')).map(c=>c.dataset.projectUrl);if(!urls.length){formError(t('اختر ملفاً واحداً على الأقل','Choose at least one file'));break;}try{await api('grabDownload',{id,urls});closeModal();navigate('all');await refresh();}catch(e){formError(e);}break;}
  case'toggleIntegration':await action('settings',{integration:!state.settings.integration});renderIntegration();break;
  case'copyToken':try{await navigator.clipboard.writeText(state.extensionToken);toast(t('تم نسخ رمز الربط','Pairing token copied'));}catch{toast(t('حدد الرمز وانسخه يدوياً','Select the token and copy it manually'));}break;
  case'rotateToken':await action('extensionRotate');renderIntegration();break;
  case'saveSettings':await saveSettings();break;
  case'browseSetting':case'browseSound':{const dir=await action(name==='browseSound'?'chooseSound':'chooseDirectory');if(dir)$(`[name="${el.dataset.field}"]`).value=dir;break;}
  case'playSound':await action('playSound',{path:$(`[name="${el.dataset.field}"]`).value});break;
  case'addLogin':{try{await api('login',{host:$('[name="loginHost"]').value,username:$('[name="loginUsername"]').value,password:$('[name="loginPassword"]').value});captureSettings();await refresh();showSettings();toast(t('تم حفظ الحساب','Login saved'));}catch(e){formError(e);}break;}
  case'removeLogin':await action('loginRemove',{host:el.dataset.host});captureSettings();showSettings();break;
  case'vpnConnect':case'vpnDisconnect':await action('settings',{vpnName:$('[name="vpnName"]').value});await action(name);break;
 }
}
document.addEventListener('click',async e=>{
 const v=e.target.closest('[data-view]');if(v){e.preventDefault();if(v.dataset.view==='settings')openSettings();else navigate(v.dataset.view);return;}
 const a=e.target.closest('[data-action]');if(a){e.preventDefault();try{await handleAction(a.dataset.action,a);}catch(err){toast(err.message,true);}return;}
 const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;page=1;updateDownloads();return;}
 const tab=e.target.closest('[data-settings-tab]');if(tab){captureSettings();settingsTab=tab.dataset.settingsTab;showSettings();return;}
 const dt=e.target.closest('[data-detail-tab]');if(dt){$$('[data-detail-tab]').forEach(b=>b.classList.toggle('active',b===dt));for(const key of ['status','speed','options'])$('#detail-tab-'+key)?.classList.toggle('hide',dt.dataset.detailTab!==key);return;}
 const q=e.target.closest('[data-queue]');if(q){queueId=q.dataset.queue;renderQueues();return;}
 const s=e.target.closest('[data-sort]');if(s){sortAsc=sort===s.dataset.sort?!sortAsc:true;sort=s.dataset.sort;updateDownloads();return;}
 const row=e.target.closest('.download-row');if(row&&!e.target.closest('input')){const id=row.dataset.id,files=filteredDownloads();if(e.shiftKey&&anchorId){const a=files.findIndex(d=>d.id===anchorId),b=files.findIndex(d=>d.id===id);if(a>=0&&b>=0)files.slice(Math.min(a,b),Math.max(a,b)+1).forEach(d=>selected.add(d.id));}else if(e.ctrlKey||e.metaKey){selected.has(id)?selected.delete(id):selected.add(id);}else selected=new Set([id]);anchorId=id;updateSelection();}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;page=1;updateDownloads();}});
document.addEventListener('change',e=>{
 const el=e.target;if(el.dataset.select){if(el.checked)selected.add(el.dataset.select);else selected.delete(el.dataset.select);updateDownloads();}
 if(el.id==='select-all'){const visible=filteredDownloads().slice((page-1)*12,page*12);for(const d of visible)el.checked?selected.add(d.id):selected.delete(d.id);updateDownloads();}
 if(el.name==='hideHTML')$$('[data-kind="html"]').forEach(row=>{row.classList.toggle('hide',el.checked);});
 if(el.name==='template'){const data={offline:['',true],images:['jpg png gif webp svg avif',false],audio:['mp3 wav ogg flac m4a',false],archives:['zip rar 7z tar gz',false],custom:['',false]}[el.value];$('[name="extensions"]').value=data[0];$('[name="includeHTML"]').checked=data[1];}
});
$('#dialog').addEventListener('close',()=>{if(!$('#dialog').open){detailId=null;settingsDraft=null;}});
document.addEventListener('keydown',e=>{if(e.ctrlKey&&e.key.toLowerCase()==='n'){e.preventDefault();if(state){if(window.desktopAPI)api('window',{kind:'add'}).catch(e=>toast(e.message,true));else openAdd();}}if(e.key==='Escape')detailId=null;});
document.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('text/uri-list'))e.preventDefault();});
document.addEventListener('drop',e=>{const url=e.dataTransfer.getData('text/uri-list')||e.dataTransfer.getData('text/plain');if(/^https?:\/\//.test(url)){e.preventDefault();const first=url.split('\n')[0];if(window.desktopAPI)api('window',{kind:'add',url:first}).catch(e=>toast(e.message,true));else openAdd(first);}});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>4*1024*1024)throw Error(t('الملف أكبر من 4 MB','File is larger than 4 MB'));const payload=JSON.parse(await file.text());const result=await api('import',payload);await refresh();toast(`${result} ${t('تحميلات تم استيرادها','downloads imported')}`);}catch(err){toast(err.message,true);}e.target.value='';});
window.desktopAPI?.onClipboard(url=>{if(!$('#dialog').open&&!windowContext){if(!nativeTool('add',{url}))openAdd(url);}});
async function init(){try{if(!window.desktopAPI){const res=await fetch('/api/session');session=(await res.json()).token;}await refresh();}catch(e){toast(e.message,true);}refreshTimer=setInterval(refresh,1000);}

